node --input-type=module -e "
import { normalizeKey } from './src/keys.js';
import { createCache } from './src/cache.js';
const clock = { now: () => 0 };
const c = createCache({ clock });
c.set('Alpha', 'A');
c.set('alpha', 'B');
console.log('normalizeKey(\"Alpha\") =', JSON.stringify(normalizeKey('Alpha')));
console.log('normalizeKey(\"alpha\") =', JSON.stringify(normalizeKey('alpha')));
console.log('size after set Alpha,alpha =', c.size());
console.log('get(\"Alpha\") =', JSON.stringify(c.get('Alpha')));
console.log('get(\"alpha\") =', JSON.stringify(c.get('alpha')));
"
